package org.traccar.protocol;

import io.netty.channel.Channel;
import org.junit.Assert;
import org.junit.Test;
import org.mockito.Mockito;
import org.traccar.Protocol;
import org.traccar.helper.Parser;
import org.traccar.model.Position;

import java.net.InetSocketAddress;
import java.net.SocketAddress;

public class WatchProtocolDecoderTest {

    @Test
    public void getHasIndexTest() {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(new Protocol("test-protocol", null));
        Assert.assertFalse(decoder.getHasIndex());
    }

    @Test
    public void getManufacturerTest() {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(new Protocol("test-protocol1", null));
        Assert.assertNull(decoder.getManufacturer());
    }

    @Test 
    public void decodeReturnNullChannelNullMsgTest() throws Exception {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(new Protocol("test-protocol2", null));
        Channel channel = null;
        SocketAddress remoteAddress = new InetSocketAddress("localhost", 8080);
        Object msg = null;
        Assert.assertNull(decoder.decode(channel, remoteAddress, msg));
    }

    @Test 
    public void decodeReturnNullMsgEmptyTest() throws Exception {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(new Protocol("test-protocol3", null));
        Channel channel = Mockito.mock(Channel.class);
        SocketAddress remoteAddress = new InetSocketAddress("localhost", 8080);
        Object msg = "";
        Assert.assertNull(decoder.decode(channel, remoteAddress, msg));
    }

    @Test 
    public void decodeReturnPositionTest() throws Exception {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(new Protocol("test-protocol4", null));
        Channel channel = Mockito.mock(Channel.class);
        SocketAddress remoteAddress = new InetSocketAddress("localhost", 8080);
        Object msg = "[SG*8800001015*0004*LK]";
        Object decoded = decoder.decode(channel, remoteAddress, msg);
        Assert.assertTrue(decoded instanceof Position);
    }
}
